/* One floor per floored command port (§05) — born-disarmed, safe at boot. */
static Floor g_floor_motor_left;
static uint16_t g_applied_seq_motor_left = 0;  /* last command seq we handed the floor */
#define FLOOR_WINDOW_MS_MOTOR_LEFT (FLOOR_MISSES_WHEELS_MOTOR_LEFT * CMD_PERIOD_MS_WHEELS_MOTOR_LEFT)
static Floor g_floor_motor_right;
static uint16_t g_applied_seq_motor_right = 0;  /* last command seq we handed the floor */
#define FLOOR_WINDOW_MS_MOTOR_RIGHT (FLOOR_MISSES_WHEELS_MOTOR_RIGHT * CMD_PERIOD_MS_WHEELS_MOTOR_RIGHT)
/* Per-sensor seq — advanced only on a real new value (§04). */
static uint16_t g_seq_vel_left = 0;
static uint16_t g_seq_vel_right = 0;
/* Per-status-port seq. */
static uint16_t g_status_seq_status_left = 0;
static uint16_t g_status_seq_status_right = 0;
/* A command for motor_left: hand the floor the RAW PACKED VALUE BYTES +
   its seq — the floor watches the seq, not the value, and stores the bytes
   opaquely (ADR-0005). Record applied_seq for the status report (§05). */
static void on_command_motor_left(const Frame *f) {
  if (f->port != PORT_WHEELS_MOTOR_LEFT) return;
  if (f->payload_len < 4) return;
  floor_on_command(&g_floor_motor_left, f->seq, f->payload, f->payload_len);
  g_applied_seq_motor_left = f->seq;
}

/* A command for motor_right: hand the floor the RAW PACKED VALUE BYTES +
   its seq — the floor watches the seq, not the value, and stores the bytes
   opaquely (ADR-0005). Record applied_seq for the status report (§05). */
static void on_command_motor_right(const Frame *f) {
  if (f->port != PORT_WHEELS_MOTOR_RIGHT) return;
  if (f->payload_len < 4) return;
  floor_on_command(&g_floor_motor_right, f->seq, f->payload, f->payload_len);
  g_applied_seq_motor_right = f->seq;
}
/* The drive loop — period 0 so it runs every loop pass, never starved (§08).
   Each floor gates its own port: target while armed, safe action otherwise
   (default safe). The floor hands back the PACKED VALUE BYTES (ADR-0005); the
   glue decodes them to the hook's typed param. Then the optional per-loop
   device hook (telemetry). */
static void control_tick(uint32_t now_us) {
  uint32_t now_ms = now_us / 1000u;
  uint8_t drive_motor_left[FLOOR_MAX_VALUE];
  floor_tick(&g_floor_motor_left, now_ms, drive_motor_left);
  wheels_motor_left_drive(be_get_f32(&drive_motor_left[0]));
  uint8_t drive_motor_right[FLOOR_MAX_VALUE];
  floor_tick(&g_floor_motor_right, now_ms, drive_motor_right);
  wheels_motor_right_drive(be_get_f32(&drive_motor_right[0]));
  wheels_post_control();
}
/* IN ports are event-driven via on_command; the scheduled cmd tick is a no-op. */
static void motor_left_cmd_tick(uint32_t now_us) { (void)now_us; }
static void motor_right_cmd_tick(uint32_t now_us) { (void)now_us; }
/* Report status_left's reported truth (§05): the paired floor's applied_seq +
   floored? flag, so the host reads truth instead of inferring it. */
static void status_left_sample_tick(uint32_t now_us) {
  (void)now_us; /* status omits t_dev, so the tick needs no clock */
  Frame f;
  f.node = MY_NODE;
  f.port = PORT_WHEELS_STATUS_LEFT;
  f.seq = ++g_status_seq_status_left;
  f.stamped = PORT_WHEELS_STATUS_LEFT_STAMPED;
  f.t_dev = 0;

  be_put_u16(&f.payload[0], g_applied_seq_motor_left);
  f.payload[2] = g_floor_motor_left.armed ? 0 : 1; /* floored? = not armed */
  f.payload_len = 3;

  link_send_up(&f);
}

/* Report status_right's reported truth (§05): the paired floor's applied_seq +
   floored? flag, so the host reads truth instead of inferring it. */
static void status_right_sample_tick(uint32_t now_us) {
  (void)now_us; /* status omits t_dev, so the tick needs no clock */
  Frame f;
  f.node = MY_NODE;
  f.port = PORT_WHEELS_STATUS_RIGHT;
  f.seq = ++g_status_seq_status_right;
  f.stamped = PORT_WHEELS_STATUS_RIGHT_STAMPED;
  f.t_dev = 0;

  be_put_u16(&f.payload[0], g_applied_seq_motor_right);
  f.payload[2] = g_floor_motor_right.armed ? 0 : 1; /* floored? = not armed */
  f.payload_len = 3;

  link_send_up(&f);
}
/* Sense vel_left (§08): one bounded read, pack big-endian, send up. A read
   that fails returns → no write → the seq stalls → the reader goes stale. */
static void vel_left_sample_tick(uint32_t now_us) {
  WheelSpeed raw;
  if (!wheels_vel_left_read(&raw)) return;

  Frame f;
  f.node = MY_NODE;
  f.port = PORT_WHEELS_VEL_LEFT;
  f.seq = ++g_seq_vel_left;        /* advance only on a real new value */
  f.stamped = PORT_WHEELS_VEL_LEFT_STAMPED;
  f.t_dev = 0;
  (void)now_us;

  be_put_f32(&f.payload[0], raw.rad_s);
  f.payload_len = 4;

  link_send_up(&f);
}

/* Sense vel_right (§08): one bounded read, pack big-endian, send up. A read
   that fails returns → no write → the seq stalls → the reader goes stale. */
static void vel_right_sample_tick(uint32_t now_us) {
  WheelSpeed raw;
  if (!wheels_vel_right_read(&raw)) return;

  Frame f;
  f.node = MY_NODE;
  f.port = PORT_WHEELS_VEL_RIGHT;
  f.seq = ++g_seq_vel_right;        /* advance only on a real new value */
  f.stamped = PORT_WHEELS_VEL_RIGHT_STAMPED;
  f.t_dev = 0;
  (void)now_us;

  be_put_f32(&f.payload[0], raw.rad_s);
  f.payload_len = 4;

  link_send_up(&f);
}
static Router g_router;

static void deliver_local(const Frame *f, void *) {
  if (f->port == PORT_WHEELS_MOTOR_LEFT) on_command_motor_left(f);
  else if (f->port == PORT_WHEELS_MOTOR_RIGHT) on_command_motor_right(f);
}
static void send_on_link(uint8_t link, const Frame *f, void *) {
  link_send_on_link(link, f); /* leaf: only link 0 (up toward the parent) is ever requested */
}


/* Meaning-blind inbound (§04): decode the body (CRC-clean at the seam), learn
   t_dev-ness per port just-in-time, route by NODE → a LOCAL LINK INDEX
   (ADR-0006). seq/t_dev never touched. */
extern "C" void hub_on_body(const uint8_t *body, size_t len) {
  if (len < FRAME_HEADER_BASE_SIZE) return;
  Frame f;
  bool stamped = wire_port_stamped(body[0], body[1]); /* per-port t_dev (§04) */
  if (!frame_decode_body(body, len, stamped, &f)) return;
  RouterSinks sinks = {deliver_local, send_on_link, nullptr};
  router_route(&g_router, &f, &sinks);
}
extern "C" void hub_setup(void) {
  /* born-disarmed floors first (§05), so the safe output is selected before any drive */
  floor_init(&g_floor_motor_left, FLOOR_WINDOW_MS_MOTOR_LEFT, SAFE_WHEELS_MOTOR_LEFT, SAFE_N_WHEELS_MOTOR_LEFT); /* %{nm: 0.0} */
  floor_init(&g_floor_motor_right, FLOOR_WINDOW_MS_MOTOR_RIGHT, SAFE_WHEELS_MOTOR_RIGHT, SAFE_N_WHEELS_MOTOR_RIGHT); /* %{nm: 0.0} */

  g_router.my_node = MY_NODE;
  for (int i = 0; i < 256; i++) g_router.route_table[i] = 0; /* default: link 0, the up-link toward the parent/host */
  g_router.route_table[0x05] = LINK_LOCAL_IDX; /* MY_NODE — delivered to a local port */

  wheels_device_setup(); /* the hand-written hardware bring-up */
}
/* The schedule (§08): one {period_us, tick} row per port from its rate. The
   drive loop runs EVERY loop (period 0) and is prepended here, never starved. */
static Task wheels_tasks[] = {
  { 0, 0, control_tick },  /* period 0 → every loop pass */
  { 20000, 0, motor_left_cmd_tick }  /* motor_left @ 50 Hz */,
  { 20000, 0, vel_left_sample_tick }  /* vel_left @ 50 Hz */,
  { 20000, 0, status_left_sample_tick }  /* status_left @ 50 Hz */,
  { 20000, 0, status_right_sample_tick }  /* status_right @ 50 Hz */,
  { 20000, 0, vel_right_sample_tick }  /* vel_right @ 50 Hz */,
  { 20000, 0, motor_right_cmd_tick }  /* motor_right @ 50 Hz */
};
#define WHEELS_N_TASKS (sizeof(wheels_tasks) / sizeof(wheels_tasks[0]))

extern "C" Task *hub_tasks(size_t *n_tasks) {
  *n_tasks = WHEELS_N_TASKS;
  return wheels_tasks;
}
